const res = await fetch('https://api.example.com/v1/weather?city=北京&unit=c');
const data = await res.json();
console.log(data);

const target = 'https://api.example.com/v1/weather?city=北京';

// GET：站点内页面直接写相对路径即可
const res = await fetch('/v1/proxy?url=' + encodeURIComponent(target));
console.log(await res.json());

// POST：JSON 请求体原样转发，也可以直接把目标写进 body
const post = await fetch('/v1/proxy', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ url: target, prompt: '你好' })
});
console.log(await post.json());
